<?php $approved=$statement['status']==='approved';$method=$approved?$statement['pricing_method_snapshot']:$statement['pricing_method'];$isBoq=$method==='boq';$status=['draft'=>'مسودة','approved'=>'معتمد','cancelled'=>'ملغي'][$statement['status']]??$statement['status'];$client=$approved?$statement['client_name_snapshot']:$statement['current_client_name'];$project=$approved?$statement['project_code_snapshot'].' - '.$statement['project_name_snapshot']:$statement['current_project_code'].' - '.$statement['current_project_name'];$contract=$approved?$statement['contract_code_snapshot']:$statement['current_contract_code'];?>
<div class="page-header mb-4"><div class="row align-items-center"><div class="col"><div class="page-pretitle"><?=e($statement['statement_code'])?></div><h2 class="page-title">مستخلص العميل</h2></div><div class="col-auto d-flex gap-2"><?php if($approved):?><a class="btn" target="_blank" href="/client-progress-statements/<?=(int)$statement['id']?>/print">طباعة</a><?php endif;?><?php if($statement['status']==='draft'&&$canEdit):?><a class="btn" href="/client-progress-statements/<?=(int)$statement['id']?>/edit">تعديل</a><?php endif;?></div></div></div>
<div class="card mb-4"><div class="card-body"><div class="row g-3"><?php foreach(['الحالة'=>$status,'طريقة التسعير'=>$isBoq?'BOQ':'Cost Plus','رقم المستخلص'=>$statement['statement_number']?:'—','التسلسل'=>$statement['statement_sequence']?:'—','التاريخ'=>$statement['statement_date'],'العقد'=>$contract,'المشروع'=>$project,'العميل'=>$client]as$l=>$v):?><div class="col-md-3"><div class="text-secondary small"><?=$l?></div><div class="fw-bold"><?=e((string)$v)?></div></div><?php endforeach;?></div></div></div>
<?php if($isBoq):?><div class="card mb-4"><div class="card-header"><h3 class="card-title">بنود جدول الكميات</h3></div><div class="table-responsive"><table class="table card-table"><thead><tr><th>البند</th><th>الوحدة</th><th>كمية العقد</th><th>السابق</th><th>الحالي</th><th>التراكمي</th><th>سعر الوحدة</th><th>قيمة الحالي</th></tr></thead><tbody><?php $section=null;foreach($boqItems as$x):?><?php if($section!==$x['section_code']):$section=$x['section_code'];?><tr class="table-active"><th colspan="8"><?=e($x['section_code'].' - '.$x['section_title'])?></th></tr><?php endif;?><tr><td><?=e(($x['item_code']?$x['item_code'].' - ':'').$x['description'])?></td><td><?=e(trim((string)($x['unit_name']??'').' '.(string)($x['unit_symbol']??''))?:'—')?></td><td><?=e((string)$x['contract_quantity'])?></td><td><?=e((string)($x['previous_quantity']??$x['display_previous_quantity']))?></td><td><?=e((string)$x['current_quantity'])?></td><td><?=e((string)($x['cumulative_quantity']??'—'))?></td><td><?=decimal_format($x['unit_rate'])?></td><td><?=decimal_format($x['current_amount']??'0.00')?></td></tr><?php endforeach;?></tbody></table></div></div><?php else:?><div class="card mb-4"><div class="card-header"><h3 class="card-title">التكاليف الحالية</h3></div><div class="table-responsive"><table class="table card-table"><thead><tr><th>التاريخ</th><th>القسم / الكود</th><th>المورد</th><th>الوصف</th><th>المبلغ</th></tr></thead><tbody><?php foreach($costs as$x):?><tr><td><?=e((string)($x['cost_date_snapshot']??'—'))?></td><td><?=e(($x['work_section_code_snapshot']??'—').' / '.($x['cost_code_snapshot']??'—'))?></td><td><?=e($x['vendor_name_snapshot']??'—')?></td><td><?=e($x['description_snapshot']??'—')?></td><td><?=decimal_format($x['amount_snapshot']??'0.00')?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
<?php if($variations):?><div class="card mb-4"><div class="card-header"><h3 class="card-title">التعديلات</h3></div><div class="table-responsive"><table class="table card-table"><thead><tr><th>التعديل</th><th>الأثر</th><th>السابق</th><th>الحالي</th><th>التراكمي</th></tr></thead><tbody><?php foreach($variations as$v):?><tr><td><?=e(($v['variation_code_snapshot']??'—').' - '.($v['variation_title_snapshot']??''))?></td><td><?=$v['amount_effect_snapshot']==='decrease'?'خصم':'زيادة'?></td><td><?=decimal_format($v['previous_billed_amount']??'0')?></td><td><?=decimal_format($v['signed_current_amount']??'0')?></td><td><?=decimal_format($v['cumulative_billed_amount']??'0')?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
<?php if($approved):?><div class="card mb-4"><div class="card-header"><h3 class="card-title">الملخص المالي</h3></div><div class="table-responsive"><table class="table card-table text-center"><thead><tr><th>البيان</th><th>السابق</th><th>الحالي</th><th>التراكمي</th></tr></thead><tbody><?php if($isBoq):?><tr><td>جدول الكميات</td><td><?=decimal_format($statement['previous_boq_amount'])?></td><td><?=decimal_format($statement['current_boq_amount'])?></td><td><?=decimal_format($statement['cumulative_boq_amount'])?></td></tr><?php else:?><tr><td>التكاليف</td><td><?=decimal_format($statement['previous_cost_amount'])?></td><td><?=decimal_format($statement['current_cost_amount'])?></td><td><?=decimal_format($statement['cumulative_cost_amount'])?></td></tr><tr><td>Markup</td><td><?=decimal_format($statement['previous_markup_amount'])?></td><td><?=decimal_format($statement['current_markup_amount'])?></td><td><?=decimal_format($statement['cumulative_markup_amount'])?></td></tr><?php endif;?><tr><td>التعديلات</td><td><?=decimal_format($statement['previous_variation_amount'])?></td><td><?=decimal_format($statement['current_variation_amount'])?></td><td><?=decimal_format($statement['cumulative_variation_amount'])?></td></tr><tr class="fw-bold"><td>إجمالي المستخلص</td><td><?=decimal_format($statement['previous_statement_amount'])?></td><td><?=decimal_format($statement['current_statement_amount'])?></td><td><?=decimal_format($statement['cumulative_statement_amount'])?></td></tr></tbody></table></div></div><?php endif;?>
<?php if($statement['status']==='draft'):?><div class="d-flex gap-2"><?php if($canApprove):?><form class="js-confirm-form" data-confirm="سيتم تجميد جميع القيم ولن يمكن تعديل المستخلص بعد الاعتماد." method="post" action="/client-progress-statements/<?=(int)$statement['id']?>/approve"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-success">اعتماد المستخلص</button></form><?php endif;?><?php if($canCancel):?><form class="js-confirm-form" data-confirm="هل تريد إلغاء هذه المسودة؟" method="post" action="/client-progress-statements/<?=(int)$statement['id']?>/cancel"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-danger">إلغاء المسودة</button></form><?php endif;?></div><?php endif;?>
